(function(root){'use strict';const S=root.KERN_SHAPES||(typeof require==='function'?require('./room-shapes.js'):null);
function point(p,rooms,exclude,tolerance){let best=null;for(const r of rooms){if(exclude.has(r.id))continue;for(const q of S.points(r)){const distance=Math.hypot(q[0]-p.x,q[1]-p.y);if(distance<=tolerance&&(!best||distance<best.distance))best={x:q[0],y:q[1],distance,kind:'vertex',room:r.id};}}if(best)return best;for(const r of rooms){if(exclude.has(r.id))continue;for(const e of S.edges(r)){const q=S.project(p,e);if(q.distance<=tolerance&&(!best||q.distance<best.distance))best={x:q.p[0],y:q.p[1],distance:q.distance,kind:'edge',edge:e,room:r.id};}}return best;}
function translation(r,rooms,exclude,tolerance){let best=null;for(const p of S.points(r)){const snap=point({x:p[0],y:p[1]},rooms,exclude,tolerance);if(snap&&(!best||snap.distance<best.distance))best={...snap,dx:snap.x-p[0],dy:snap.y-p[1]};}for(const other of rooms){if(exclude.has(other.id))continue;for(const p of S.points(other)){for(const edge of S.edges(r)){const q=S.project({x:p[0],y:p[1]},edge);if(q.distance<=tolerance&&(!best||q.distance<best.distance))best={x:p[0],y:p[1],distance:q.distance,dx:p[0]-q.p[0],dy:p[1]-q.p[1],kind:'vertex',room:other.id};}}}return best;}
function angle(r,delta,rooms,exclude,tolerance=4){let best=null;for(const e of S.edges(r).filter(e=>!e.curved)){const source=Math.atan2(e.b[1]-e.a[1],e.b[0]-e.a[0])*180/Math.PI;for(const other of rooms){if(exclude.has(other.id))continue;for(const edge of S.edges(other).filter(e=>!e.curved)){const target=Math.atan2(edge.b[1]-edge.a[1],edge.b[0]-edge.a[0])*180/Math.PI;let diff=((target-source-delta)%180+270)%180-90;if(Math.abs(diff)<=tolerance&&(!best||Math.abs(diff)<Math.abs(best.diff)))best={delta:delta+diff,diff,edge,kind:'angle',room:other.id};}}}return best;}
const api={point,translation,angle};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.KERN_ROOM_SNAP=api;
})(typeof window!=='undefined'?window:globalThis);
